/**
 * Reads scripts/url-migration-data/redirects_preview.csv (S0 gold)
 * and writes src/lib/seo/redirect-map.generated.ts.
 *
 * Do not edit the generated file by hand — re-run: npm run generate:redirects
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

/** Keep in sync with src/lib/seo/normalize-redirect-path.ts */
function normalizeRedirectPath(raw) {
  let path = raw.trim();
  try {
    path = decodeURIComponent(path);
  } catch {
    // keep raw
  }
  path = path.normalize("NFC");
  if (!path.startsWith("/")) path = `/${path}`;
  const segments = path
    .split("/")
    .filter((s) => s.length > 0)
    .map((seg) => (/^[a-zA-Z0-9_-]+$/.test(seg) ? seg.toLowerCase() : seg));
  if (segments.length === 0) return "/";
  return `/${segments.join("/")}/`;
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const csvPath = join(root, "scripts/url-migration-data/redirects_preview.csv");
const outPath = join(root, "src/lib/seo/redirect-map.generated.ts");

function parseCsv(text) {
  const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).filter((l) => l.length > 0);
  if (lines.length < 2) throw new Error("CSV empty");
  const header = lines[0].split(",");
  const gi = header.indexOf("group");
  const oi = header.indexOf("old_url");
  const ni = header.indexOf("new_url");
  if (gi < 0 || oi < 0 || ni < 0) {
    throw new Error(`CSV missing columns: ${header.join(",")}`);
  }

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(",");
    const group = parts[gi];
    const old_url = parts[oi];
    const new_url = parts[ni];
    if (!group || !old_url || !new_url) {
      throw new Error(`Invalid row ${i + 1}: ${lines[i]}`);
    }
    rows.push({ group, old_url, new_url });
  }
  return rows;
}

function main() {
  const rows = parseCsv(readFileSync(csvPath, "utf8"));
  const entries = new Map();
  const stats = { a: 0, b: 0, c: 0, total: 0 };

  for (const row of rows) {
    const oldPath = normalizeRedirectPath(row.old_url);
    const newPath = normalizeRedirectPath(row.new_url);
    if (!oldPath || !newPath) {
      throw new Error(`Empty path after normalize: ${row.old_url} → ${row.new_url}`);
    }
    if (oldPath === newPath) {
      throw new Error(`old === new after normalize: ${oldPath}`);
    }
    if (entries.has(oldPath)) {
      const prev = entries.get(oldPath);
      if (prev !== newPath) {
        throw new Error(
          `Duplicate old_url conflict: ${oldPath} → ${prev} vs ${newPath}`,
        );
      }
      continue;
    }
    entries.set(oldPath, newPath);
    if (row.group === "a-muru-ru") stats.a += 1;
    else if (row.group === "b-orphan-muru-ru") stats.b += 1;
    else if (row.group === "c-cyrillic-staging") stats.c += 1;
    else throw new Error(`Unknown group: ${row.group}`);
  }

  stats.total = entries.size;

  for (const [, target] of entries) {
    if (entries.has(target)) {
      throw new Error(`Chain detected: target is also a source: ${target}`);
    }
  }

  const pairs = [...entries.entries()]
    .map(([from, to]) => `  [${JSON.stringify(from)}, ${JSON.stringify(to)}]`)
    .join(",\n");

  const body = `/* eslint-disable */
/**
 * AUTO-GENERATED by scripts/generate-redirects.ts — do not edit by hand.
 * Source: scripts/url-migration-data/redirects_preview.csv
 * Regenerate: npm run generate:redirects
 */
export const REDIRECT_MAP_STATS = {
  a: ${stats.a},
  b: ${stats.b},
  c: ${stats.c},
  total: ${stats.total},
} as const;

export const REDIRECT_MAP: ReadonlyMap<string, string> = new Map([
${pairs},
]);

/** Reserved for 410 Gone; S0 map had none. */
export const GONE_PATHS: ReadonlySet<string> = new Set();
`;

  writeFileSync(outPath, body, "utf8");
  console.log(
    `Wrote ${outPath} — total=${stats.total} a=${stats.a} b=${stats.b} c=${stats.c}`,
  );
}

main();
